#include <array>
#include <iostream>
#include <vector>
#include <functional>
using namespace std;
int rank_cross(const vector<int>&r,int root){vector<int>O,I;for(int v=0;v<(int)r.size();v++)if(v!=root)((r[root]>>v&1)?O:I).push_back(v);vector<int>partner(r.size(),-1);function<bool(int,vector<bool>&)> aug=[&](int v,vector<bool>&seen){for(int w:I)if((r[v]>>w&1)&&!seen[w]){seen[w]=true;if(partner[w]<0||aug(partner[w],seen)){partner[w]=v;return true;}}return false;};int rank=0;for(int v:O){vector<bool>seen(r.size());rank+=aug(v,seen);}return rank;}
array<long long,5> gap_runs(const vector<int>&r,int root){vector<int>old;for(int v=0;v<(int)r.size();v++)if(v!=root)old.push_back(v);int n=old.size(),N=1<<n;vector<array<long long,5>>dp(N*n);for(int v=0;v<n;v++){dp[(1<<v)*n+v][0]=1;dp[(1<<v)*n+v][1]=(r[root]>>old[v]&1);}for(int M=1;M<N;M++)for(int u=0;u<n;u++)if(M>>u&1)for(int v=0;v<n;v++)if(!(M>>v&1)){int direct=r[old[u]]>>old[v]&1;int gap=(r[old[u]]>>root&1)&&(r[root]>>old[v]&1);auto &a=dp[M*n+u],&b=dp[(M|1<<v)*n+v];for(int k=0;k<5;k++){b[k]+=direct*a[k];if(k<4)b[k+1]+=gap*a[k];}}array<long long,5>a{};for(int u=0;u<n;u++){int end=r[old[u]]>>root&1;for(int k=0;k<5;k++){a[k]+=dp[(N-1)*n+u][k];if(k<4)a[k+1]+=end*dp[(N-1)*n+u][k];}}return a;}
int main(){int entries;cin>>entries;int roots=0,first=0,hits=0;for(int i=0;i<entries;i++){int n,H;cin>>n>>H;vector<int>r(n);for(int&x:r)cin>>x;if(H%6!=1)continue;for(int root=0;root<n;root++)if(rank_cross(r,root)==2){roots++;auto a=gap_runs(r,root);if(a[1]!=H||a[4]){cerr<<"run failure";return 1;}if(a[2]==H-1){first++;if(3*a[3]==H-1){hits++;cerr<<"hit n="<<n<<" root="<<root<<" H="<<H<<" a0="<<a[0]<<" a1="<<a[1]<<" a2="<<a[2]<<" a3="<<a[3]<<"\n";}}}}cout<<"{\"graphs\":"<<entries<<",\"rank_two_roots\":"<<roots<<",\"first_equation\":"<<first<<",\"hits\":"<<hits<<"}\n";return hits==1?0:2;}
